    if hits:
        results.append(("Verboden placeholders (poort N)", "FAIL",
                         f"{len(hits)} treffer(s): " + "; ".join(hits)))
    else:
        results.append(("Verboden placeholders (poort N)", "OK",
                         f"Geen verboden placeholders gevonden in {user_dir}."))


